void plotCirclePoints(int xc, int yc, int x, int y) {
    printf("(%d, %d) ", xc + x, yc + y);
    printf("(%d, %d) ", xc - x, yc + y);
    printf("(%d, %d) ", xc + x, yc - y);
    printf("(%d, %d)\n", xc - x, yc - y);
}

void bresenhamCircle(int xc, int yc, int r) {
    int x = 0, y = r;
    int d = 3 - 2 * r;
    while (y >= x) {
        plotCirclePoints(xc, yc, x, y);
        x++;
        if (d > 0) { y--; d = d + 4 * (x - y) + 10; }
        else { d = d + 4 * x + 6; }
    }
}

